// CONFIGURATION - set via n8n env vars or edit directly
const config = {
  GITHUB_OWNER: $env.GITHUB_OWNER || 'your-org-or-user',
  GITHUB_REPO: $env.GITHUB_REPO || 'your-repo',
  GITHUB_TOKEN: $env.GITHUB_TOKEN || '',
  ANTHROPIC_API_KEY: $env.ANTHROPIC_API_KEY || '',
  DISCORD_WEBHOOK_URL: $env.DISCORD_WEBHOOK_URL || '',
  SUMMARY_LANGUAGE: $env.SUMMARY_LANGUAGE || 'EN',
  CLAUDE_MODEL: 'claude-sonnet-4-20250514',
};
const now = new Date();
const weekAgo = new Date(now.getTime() - 7*24*60*60*1000);
return [{ json: { ...config, SINCE_DATE: weekAgo.toISOString(), UNTIL_DATE: now.toISOString(),
  WEEK_START: weekAgo.toLocaleDateString('en-US',{month:'short',day:'numeric'}),
  WEEK_END: now.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}) }}];

const allItems = $input.all();
let config={},commitsRaw=null,issuesRaw=null,prsRaw=null;
for(const item of allItems){
  const d=item.json;
  if(d.GITHUB_OWNER) config=d;
  if(Array.isArray(d)){
    if(d.length>0&&d[0].commit&&d[0].sha) commitsRaw=d;
    else if(d.length>0&&d[0].pull_request) prsRaw=d;
    else if(d.length>0&&d[0].state!==undefined&&d[0].title) issuesRaw=d;
  }
}
const commits=commitsRaw||[];
const issues=(issuesRaw||[]).filter(i=>!i.pull_request);
const mergedPrs=(prsRaw||[]).filter(pr=>pr.merged_at);
const cl=commits.slice(0,30).map(c=>{
  const m=c.commit.message.split('\n')[0];
  const a=c.commit.author?.name||'unknown';
  return '- '+m+' ('+a+')';
}).join('\n');
const il=issues.slice(0,20).map(i=>{
  const lb=i.labels.map(l=>l.name).join(', ');
  return '- #'+i.number+' '+i.title+(lb?' ['+lb+']':'');
}).join('\n');
const pl=mergedPrs.slice(0,20).map(p=>
  '- PR #'+p.number+': '+p.title+' (by '+(p.user?.login||'unknown')+')'
).join('\n');
const lang=config.SUMMARY_LANGUAGE==='FR'
  ? 'Ecris le resume en francais.'
  : 'Write the summary in English.';
const prompt=`You are a technical project manager. Based on the following GitHub activity for the week of ${config.WEEK_START} to ${config.WEEK_END}, write a clear weekly summary.

COMMITS (${commits.length} total):
${cl||'(none)'}

CLOSED ISSUES (${issues.length} total):
${il||'(none)'}

MERGED PULL REQUESTS (${mergedPrs.length} total):
${pl||'(none)'}

${lang}

Structure:
1. **Overview** - One sentence on the main theme
2. **Key Accomplishments** - Bullet points
3. **Pull Requests Merged** - Brief descriptions
4. **Issues Resolved** - List
5. **Looking Ahead** - Brief note

Keep it under 300 words. Be specific with numbers and names.`;
return [{json:{...config,COMMITS_COUNT:commits.length,ISSUES_COUNT:issues.length,
  PRS_COUNT:mergedPrs.length,PROMPT:prompt,
  WEEK_LABEL:config.WEEK_START+' - '+config.WEEK_END}}];

const body = $input.first().json;
const response = await fetch('https://api.anthropic.com/v1/messages', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'x-api-key': body.ANTHROPIC_API_KEY,
    'anthropic-version': '2023-06-01',
  },
  body: JSON.stringify({
    model: body.CLAUDE_MODEL || 'claude-sonnet-4-20250514',
    max_tokens: 1024,
    messages: [{ role: 'user', content: body.PROMPT }],
  }),
});
if (!response.ok) {
  throw new Error('Claude API error ' + response.status + ': ' + await response.text());
}
const data = await response.json();
return [{ json: { ...body, SUMMARY: data.content?.[0]?.text || 'No summary generated.' } }];

const b = $input.first().json;
if (!b.DISCORD_WEBHOOK_URL) {
  throw new Error('DISCORD_WEBHOOK_URL not configured.');
}
const repo = (b.GITHUB_OWNER || '') + '/' + (b.GITHUB_REPO || '');
const embed = {
  title: '\ud83d\udcca Weekly Summary: ' + repo,
  description: b.SUMMARY,
  color: 5814783,
  fields: [
    { name: '\ud83d\udcc4 Commits', value: String(b.COMMITS_COUNT || 0), inline: true },
    { name: '\u2705 Issues Closed', value: String(b.ISSUES_COUNT || 0), inline: true },
    { name: '\ud83d\udd00 PRs Merged', value: String(b.PRS_COUNT || 0), inline: true },
  ],
  footer: { text: 'Generated by n8n \u00b7 ' + (b.WEEK_LABEL || 'This Week') },
  timestamp: new Date().toISOString(),
};
const resp = await fetch(b.DISCORD_WEBHOOK_URL, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ username: 'GitHub Activity Bot', embeds: [embed] }),
});
if (!resp.ok) {
  throw new Error('Discord webhook error ' + resp.status + ': ' + await resp.text());
}
return [{ json: { success: true, message: 'Summary delivered to Discord.' } }];
